+        data-testid='device-detail-heading-edit'
+        onSubmit={event => {
+            event.preventDefault();
+            void onSave();
+        }}
+    >
+        <Field
+            label={_t('Session name')}
+            type='text'
+            value={draftName}
+            maxLength={100}
+            autoComplete='off'
