+            { error }
+        </p> }
+        <div className='mx_DeviceDetailHeading_actions'>
+            <AccessibleButton
+                element='button'
+                type='submit'
+                kind='primary_sm'
+                disabled={isSaving}
+                onClick={event => {
+                    event.preventDefault();
+                    void onSave();
+                }}
+                data-testid='device-detail-save-button'
+            >
+                { _t('Save') }
+                { isSaving && <span data-testid='device-detail-save-spinner'><Spinner w={16} h={16} /></span> }
+            </AccessibleButton>
+            <AccessibleButton
+                element='button'
+                type='button'
+                kind='link_inline'
+                disabled={isSaving}
+                onClick={onCancel}
